<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, ref } from 'vue';
import { Link, router } from '@inertiajs/vue3';
import { Sun, Moon, ListTodo, Target, Leaf, Wallet, Lightbulb, Plus, Check, ChevronRight, CalendarDays, X, ArrowUpRight } from 'lucide-vue-next';
import { request } from '../lib/api';
import HomeCalendar from './HomeCalendar.vue';
import SproutBuddy from './SproutBuddy.vue';
import { calendarPreview } from '../lib/calendarPreview';
import { watchCalendarRefresh } from '../lib/calendarRefresh';
const props=defineProps<{user:any;settings:any;today:string;data:any;summary:any;lookups:any;calendarRevision?:number}>();
const emit=defineEmits<{edit:[entity:string,record?:any,defaults?:any];capture:[type:string]}>();
const error=ref(''); const pending=ref<string[]>([]); const panel=ref<'calendar'|'finance'|null>(null); const panelDialog=ref<HTMLDialogElement>();
const celebration=ref(''); const celebrationKey=ref(0); let celebrationTimer:ReturnType<typeof setTimeout>;
function cheer(message:string){celebration.value=message;celebrationKey.value++;clearTimeout(celebrationTimer);celebrationTimer=setTimeout(()=>celebration.value='',3600);}
const idea=ref(''); const ideaBusy=ref(false); const ideaMessage=ref('');
const hour=Number(new Intl.DateTimeFormat('en-GB',{hour:'numeric',hourCycle:'h23',timeZone:props.settings.timezone||'Asia/Makassar'}).format(new Date()));
const greeting=hour<12?'Good morning':hour<18?'Good afternoon':'Good evening';
const prettyDate=computed(()=>new Date(props.today+'T12:00:00').toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long'}));
const monthLabel=computed(()=>new Date(props.today+'T12:00:00').toLocaleDateString('en-GB',{month:'short',year:'numeric'}));
const previewDays=computed(()=>{const first=new Date(props.today.slice(0,7)+'-01T12:00:00Z');const offset=(first.getUTCDay()-Number(props.settings.week_starts_on??1)+7)%7;const count=new Date(Date.UTC(first.getUTCFullYear(),first.getUTCMonth()+1,0)).getUTCDate();return Array.from({length:Math.ceil((offset+count)/7)*7},(_,i)=>i>=offset&&i<offset+count?i-offset+1:0);});
const previewWeek=computed(()=>Array.from({length:7},(_,i)=>['S','M','T','W','T','F','S'][(i+Number(props.settings.week_starts_on??1))%7]));
const previewEvents=ref<any[]>([]); const previewChecks=ref<string[]>([]); const previewLoading=ref(false); const previewError=ref(''); let previewSequence=0;
const previewState=computed(()=>calendarPreview(previewEvents.value,previewChecks.value,props.today.slice(0,7),props.settings.timezone||'Asia/Makassar'));
const dateKey=(date:number)=>`${props.today.slice(0,7)}-${String(date).padStart(2,'0')}`;
function previewTitle(date:number){const state=previewState.value[dateKey(date)];return `${dateKey(date)}: ${state?.checked?'checked in':'not checked in'}, ${state?.events||0} events`;}
async function loadPreview(){const sequence=++previewSequence;previewLoading.value=true;previewError.value='';const from=props.today.slice(0,7)+'-01';const to=props.today.slice(0,7)+'-'+String(new Date(Date.UTC(Number(props.today.slice(0,4)),Number(props.today.slice(5,7)),0)).getUTCDate());const params=new URLSearchParams({from,to,per_page:'100'});try{const [events,checks]=await Promise.all([(async()=>{const rows:any[]=[];for(let page=1;;page++){const response=await request(`/data/events?${params}&page=${page}`,'GET');if(sequence!==previewSequence)return [];rows.push(...response.data);if(page>=response.last_page)return rows;}})(),request(`/daily-checkins?${params}`,'GET')]);if(sequence===previewSequence){previewEvents.value=events;previewChecks.value=checks.dates;}}catch(e:any){if(sequence===previewSequence)previewError.value=e.message;}finally{if(sequence===previewSequence)previewLoading.value=false;}}
function updateCheckin(date:string,checked:boolean){previewChecks.value=checked?[...new Set([...previewChecks.value,date])]:previewChecks.value.filter(value=>value!==date);}
watchCalendarRefresh(()=>({data:props.data,range:props.today.slice(0,7),timezone:props.settings.timezone,revision:props.calendarRevision}),loadPreview);
onBeforeUnmount(()=>{previewSequence++;clearTimeout(celebrationTimer);});
async function openPanel(value:'calendar'|'finance'){if(value==='calendar' && previewError.value)void loadPreview();panel.value=value;await nextTick();panelDialog.value?.showModal();}
function closePanel(){panelDialog.value?.close();panel.value=null;}
function panelEdit(entity:string,record?:any,defaults?:any){closePanel();emit('edit',entity,record,defaults);}
const stats=computed(()=>props.summary.today||{completed_count:0,total_count:0,percentage:0});
const focus=computed(()=>props.data.projects?.find((p:any)=>p.id===props.summary.current_focus_id||p.is_current_focus));
const tasks=computed(()=>(props.data.tasks||[]).filter((t:any)=>t.planned_date===props.today||t.is_today).slice(0,8));
const habits=computed(()=>(props.data.habits||[]).filter((h:any)=>h.active!==false).slice(0,8));
const finance=computed(()=>props.summary.finance||{income:'0',expenses:'0',net_savings:'0'});
function habitDayState(day:any){return day.completed?'complete':!day.scheduled?'rest':day.date>props.today?'upcoming':day.date===props.today?'pending':'missed';}
function habitDayLabel(day:any){const label={complete:'Completed',rest:'Rest day',upcoming:'Upcoming',pending:'Not completed yet',missed:'Not completed'}[habitDayState(day)];return `${day.date}: ${label}`;}
function money(amount:any){const currency=finance.value.currency||props.settings.currency||'IDR';return new Intl.NumberFormat(currency==='IDR'?'id-ID':'en-US',{style:'currency',currency,maximumFractionDigits:['IDR','JPY','KRW'].includes(currency)?0:2}).format(Number(amount||0));}
async function toggle(entity:string,id:string){if(pending.value.includes(id))return;pending.value.push(id);error.value='';try{const result=await request(`/data/${entity}/${id}/${entity==='tasks'?'complete':'toggle'}`);if(entity==='tasks'?result.data?.status==='done':result.completed===true)cheer(entity==='tasks'?'One little win. Nicely done!':'A little care, a little growth.');router.reload({onFinish:()=>pending.value=pending.value.filter(x=>x!==id)});}catch(e:any){error.value=e.message;pending.value=pending.value.filter(x=>x!==id);}}
async function saveIdea(){if(!idea.value.trim()||ideaBusy.value)return;ideaBusy.value=true;ideaMessage.value='';try{const body=idea.value.trim();await request('/quick-capture/idea','POST',{title:body.split('\n')[0].slice(0,255),body,status:'inbox'});idea.value='';ideaMessage.value='Saved to your Ideas inbox.';cheer('A new idea, ready to grow.');router.reload();}catch(e:any){ideaMessage.value=e.message;}finally{ideaBusy.value=false;}}
</script>
<template>
 <div class="glass-home">
  <header class="home-greeting"><div class="greeting-copy"><p class="eyebrow">YOUR SPACE TO GROW</p><h1>{{greeting}}, {{user.name.split(' ')[0]}} <Sun v-if="hour<18" :size="25"/><Moon v-else :size="25"/></h1><p class="muted">{{prettyDate}}</p><div class="daily-buddy"><button class="buddy-button" aria-label="Say hello to Sprout" title="Say hello to Sprout" @click="cheer('Hi, I’m Sprout. Let’s grow at your pace.')"><SproutBuddy :happy="!!celebration"/></button><span class="buddy-note">A little progress.<br/><strong>A little more you.</strong></span></div></div><div class="home-shortcuts"><button class="home-shortcut calendar-shortcut" :aria-label="`Open monthly calendar. ${previewLoading?'Loading dates.':previewError?'Preview unavailable.':'Green dates are checked in; yellow marks show events.'}`" aria-haspopup="dialog" @click="openPanel('calendar')"><span class="shortcut-copy"><CalendarDays :size="18"/><strong>{{monthLabel}}</strong><small>Calendar <ArrowUpRight :size="12"/></small><span class="preview-legend"><span><i class="checked-key"></i>Checked</span><span><i class="event-key"></i>Event</span></span><small v-if="previewLoading" role="status">Loading…</small><small v-else-if="previewError" role="status">Open to retry</small></span><span class="calendar-preview" aria-hidden="true"><span v-for="(name,i) in previewWeek" :key="'w'+i" class="preview-weekday">{{name}}</span><span v-for="(date,i) in previewDays" :key="i" :class="{'preview-today':date===Number(today.slice(8)),'preview-checked':date&&previewState[dateKey(date)]?.checked,'preview-event':date&&previewState[dateKey(date)]?.events}" :title="date?previewTitle(date):undefined">{{date||''}}<i v-if="date&&previewState[dateKey(date)]?.events" class="preview-event-dot"></i></span></span></button><button class="home-shortcut finance-shortcut" aria-label="Open finance summary" aria-haspopup="dialog" @click="openPanel('finance')"><span class="shortcut-copy"><Wallet :size="18"/><strong>Finance</strong><small>View details <ArrowUpRight :size="12"/></small></span><span class="shortcut-amount"><small>Net savings</small><strong>{{money(finance.net_savings)}}</strong></span></button></div></header>
  <section class="focus-hero card">
   <img src="/mountain-dawn.png" alt="" class="hero-landscape"/>
   <div class="hero-intention"><span class="eyebrow">TODAY’S INTENTION</span><h2>{{settings.current_intention_text||'Make space for what matters.'}}</h2><Link href="/settings" class="quiet-link">Set your direction <ArrowUpRight :size="16"/></Link></div>
   <div class="hero-focus"><span class="eyebrow"><Target :size="16"/> CURRENT FOCUS</span><h3>{{focus?.name||'Choose your next meaningful step.'}}</h3><p>{{focus?.description||'Choose an active project to keep your daily actions connected to what matters.'}}</p><template v-if="focus"><div class="hero-progress"><div class="progress-track"><span :style="{width:(focus.progress||0)+'%'}"></span></div><strong>{{focus.progress||0}}%</strong></div></template><Link :href="focus?`/projects/${focus.id}`:'/projects'" class="btn btn-secondary">{{focus?'Continue project':'Choose a focus'}} <ArrowUpRight :size="16"/></Link></div>
  </section>
  <p v-if="error" class="error-banner" role="alert">{{error}}</p>
  <div class="home-daily-grid">
   <section class="card home-tasks"><div class="card-header"><h2><ListTodo :size="21"/> Today / To Do</h2><Link href="/today" class="quiet-link">View all <ChevronRight :size="16"/></Link></div><div class="today-progress"><span>{{stats.completed_count}} of {{stats.total_count}} completed</span><strong>{{stats.percentage}}%</strong></div><div class="progress-track"><span :style="{width:stats.percentage+'%'}"></span></div><div class="home-task-list"><div v-for="task in tasks" :key="task.id" class="home-task" :class="{done:task.status==='done'}"><button class="touch-check" :aria-label="`${task.status==='done'?'Reopen':'Complete'} ${task.title}`" :aria-pressed="task.status==='done'" :disabled="pending.includes(task.id)" @click="toggle('tasks',task.id)"><span><Check v-if="task.status==='done'" :size="15"/></span></button><button class="home-task-title" @click="emit('edit','tasks',task)">{{task.title}}</button><span v-if="['high','urgent'].includes(task.priority)" class="priority-mark" :class="task.priority"></span></div><p v-if="!tasks.length" class="home-empty">A little room to breathe. Add one thing you want to move forward today.</p></div><button class="card-add" @click="emit('edit','tasks',undefined,{planned_date:today})"><Plus :size="18"/> Add a task</button></section>
   <section class="card home-habits"><div class="card-header"><h2><Leaf :size="21"/> Daily Habits</h2><Link href="/habits" class="quiet-link">View all <ChevronRight :size="16"/></Link></div><div class="habit-visual-legend"><span><i class="habit-key done"></i>Done</span><span><i class="habit-key missed"></i>Missed</span><span><i class="habit-key rest"></i>Rest / upcoming</span></div><div class="home-habit-list"><div v-for="habit in habits" :key="habit.id" class="home-habit"><button class="habit-toggle" :aria-pressed="!!habit.completed_today" :disabled="pending.includes(habit.id)||habit.scheduled_today===false" @click="toggle('habits',habit.id)"><span class="touch-check"><span><Check v-if="habit.completed_today" :size="15"/></span></span><span>{{habit.name}}<small v-if="habit.scheduled_today===false">Rest day</small></span></button><div class="habit-week-visual" :aria-label="habit.name+' this week'"><span v-for="day in habit.week||[]" :key="day.date" class="habit-visual-day" :class="[habitDayState(day),{today:day.date===today}]" role="img" :aria-label="habitDayLabel(day)" :title="habitDayLabel(day)"><small>{{new Date(day.date+'T12:00:00Z').toLocaleDateString('en-GB',{weekday:'short',timeZone:'UTC'}).slice(0,1)}}</small><span class="habit-day-cell"><Check v-if="day.completed" :size="12"/><span v-else-if="habitDayState(day)==='missed'">×</span><span v-else-if="!day.scheduled">–</span><span v-else class="habit-pending-dot"></span></span></span></div></div><p v-if="!habits.length" class="home-empty">Build a rhythm that feels like you. Start with one small habit.</p></div><button class="card-add" @click="emit('edit','habits')"><Plus :size="18"/> Add a habit</button></section>
  </div>
  <div class="home-brain-row">
   <section class="card brain-dump"><div class="card-header"><h2><Lightbulb :size="21"/> Ideas Brain Dump</h2><Link href="/ideas" class="quiet-link" aria-label="Open ideas inbox"><ArrowUpRight :size="19"/></Link></div><p class="muted">No sorting. No perfect words. Just get it out of your head.</p><form @submit.prevent="saveIdea"><label for="brain-dump" class="sr-only">Capture an idea</label><textarea id="brain-dump" v-model="idea" placeholder="What’s on your mind?" maxlength="10000" :disabled="ideaBusy" required></textarea><div class="brain-footer"><span class="muted">{{summary.inbox_ideas||0}} ideas in your inbox</span><button class="btn btn-primary" :disabled="ideaBusy||!idea.trim()">{{ideaBusy?'Saving…':'Save idea'}} <Plus :size="17"/></button></div><p v-if="ideaMessage" role="status" class="brain-status">{{ideaMessage}}</p></form></section>
  </div>
  <Transition name="little-win"><div v-if="celebration" :key="celebrationKey" class="little-win-toast" role="status"><SproutBuddy happy/><span>{{celebration}}</span><button class="btn-icon" aria-label="Dismiss celebration" @click="celebration='' "><X :size="15"/></button><span class="win-sparkles" aria-hidden="true">✦</span></div></Transition>
  <dialog ref="panelDialog" class="home-detail-modal" :class="{'calendar-modal':panel==='calendar','finance-modal':panel==='finance'}" :aria-label="panel==='calendar'?'Monthly calendar':'Finance summary'" @cancel="closePanel" @click="($event.target===panelDialog)&&closePanel()">
   <header class="home-modal-header"><div><span class="eyebrow">{{panel==='calendar'?'MAKE TIME FOR WHAT MATTERS':'YOUR MONEY, AT A GLANCE'}}</span><h2>{{panel==='calendar'?'Calendar':'Finance Summary'}}</h2></div><button class="btn-icon" aria-label="Close details" @click="closePanel"><X :size="20"/></button></header>
   <div class="home-modal-body"><HomeCalendar v-if="panel==='calendar'" :today="today" :settings="settings" :data="data" @edit="panelEdit" @checkin="updateCheckin"/>
    <template v-if="panel==='finance'"><p class="muted">{{monthLabel}} · {{finance.currency||settings.currency}}</p><div class="modal-finance-stats"><div><span>Income</span><strong>{{money(finance.income)}}</strong></div><div><span>Expenses</span><strong>{{money(finance.expenses)}}</strong></div><div><span>Net savings</span><strong>{{money(finance.net_savings)}}</strong></div></div><h3 class="finance-breakdown-title">Expense breakdown</h3><div v-for="category in finance.breakdown||[]" :key="category.category_id" class="modal-category"><span>{{category.name}}</span><strong>{{money(category.amount)}}</strong></div><p v-if="!finance.breakdown?.length" class="home-empty">No expenses recorded this month.</p><div class="modal-finance-actions"><button class="btn btn-primary" @click="panelEdit('transactions',undefined,{type:'expense',transaction_date:today})"><Plus :size="16"/> Add expense</button><button class="btn btn-secondary" @click="panelEdit('transactions',undefined,{type:'income',transaction_date:today})"><Plus :size="16"/> Add income</button><Link href="/finance" class="quiet-link" @click="closePanel">All finances <ArrowUpRight :size="16"/></Link></div></template>
   </div>
  </dialog>
 </div>
</template>
